/// SyncUI is how Go asks the app's user during pairing and the first sync
/// of a link.
///
/// Go calls Dart through the interface SyncUI in golang/ (marked with //fluffy:dart). Implement this class and pass it to [register].
abstract class SyncUI {
  /// ChooseFirstSync asks how to combine the open profile with the linked
  /// one at its first sync: "merge", "replaceOther" or "replaceThis", or
  /// "" to decide later.
  FutureOr<String> chooseFirstSync(LinkInfo link);

  /// ConfirmPairing shows the pairing code and asks whether the device
  /// named deviceName shows the same.
  FutureOr<bool> confirmPairing(String deviceName, String code);

  /// PairingFinished tells whether pairing with deviceName succeeded.
  void pairingFinished(String deviceName, bool paired);

  /// PairingRequest asks whether to accept a pairing request from the
  /// device named deviceName.
  FutureOr<bool> pairingRequest(String deviceName);

  /// Makes [impl] answer the calls of Go. Registering again replaces it.
  static void register(SyncUI impl) {
    for (final subscription in _subscriptions) {
      subscription.cancel();
    }
    _subscriptions.clear();
    receiver.handle('SyncUI.ChooseFirstSync', (data) async {
      final args = data as List<dynamic>;
      return await impl.chooseFirstSync(LinkInfo.fromJson(args[0]));
    });
    receiver.handle('SyncUI.ConfirmPairing', (data) async {
      final args = data as List<dynamic>;
      return await impl.confirmPairing(args[0] as String, args[1] as String);
    });
    _subscriptions.add(receiver.on<Object?>('SyncUI.PairingFinished').listen((data) {
      final args = data as List<dynamic>;
      impl.pairingFinished(args[0] as String, args[1] as bool);
    }));
    receiver.handle('SyncUI.PairingRequest', (data) async {
      final args = data as List<dynamic>;
      return await impl.pairingRequest(args[0] as String);
    });
  }

  static final _subscriptions = <StreamSubscription<Object?>>[];
}

