/// OptimizeEvent is progress, then the result or an error.
class OptimizeEvent {
  const OptimizeEvent({
    required this.stage,
    required this.done,
    required this.total,
    this.result,
    required this.presets,
    required this.error,
  });

  factory OptimizeEvent.fromJson(Object? json) {
    final m = json as Map<String, dynamic>;
    return OptimizeEvent(
      stage: m['stage'] as String,
      done: m['done'] as int,
      total: m['total'] as int,
      result: switch (m['result']) { final v0? => OptimizeResult.fromJson(v0), _ => null },
      presets: (m['presets'] as List<dynamic>?)?.map((x0) => PresetOptimization.fromJson(x0)).toList() ?? const <PresetOptimization>[],
      error: m['error'] as String,
    );
  }

  /// Stage is "reading" (the review history), "training", "checking"
  /// (the health check), "preset" (Optimize all: Done of Total presets
  /// finished) or "done".
  final String stage;

  final int done;

  final int total;

  /// Result is the result of Optimize, Presets that of Optimize all.
  final OptimizeResult? result;

  final List<PresetOptimization> presets;

  final String error;

  Map<String, Object?> toJson() => {
    'stage': stage,
    'done': done,
    'total': total,
    'result': switch (result) { final v0? => v0.toJson(), _ => null },
    'presets': [for (final x0 in presets) x0.toJson()],
    'error': error,
  };

  @override
  String toString() => 'OptimizeEvent(stage: $stage, done: $done, total: $total, result: $result, presets: $presets, error: $error)';
}

/// OptimizeResult is what optimizing found.
class OptimizeResult {
  const OptimizeResult({
    required this.weights,
    required this.use,
    required this.better,
    required this.reviews,
    required this.logLoss,
    required this.rmse,
    required this.currentLogLoss,
    required this.currentRMSE,
    required this.healthChecked,
    required this.healthPassed,
    required this.notEnoughReviews,
    required this.minReviews,
  });

  factory OptimizeResult.fromJson(Object? json) {
    final m = json as Map<String, dynamic>;
    return OptimizeResult(
      weights: (m['weights'] as List<dynamic>?)?.map((x0) => (x0 as num).toDouble()).toList() ?? const <double>[],
      use: m['use'] as bool,
      better: m['better'] as bool,
      reviews: m['reviews'] as int,
      logLoss: (m['logLoss'] as num).toDouble(),
      rmse: (m['rmse'] as num).toDouble(),
      currentLogLoss: (m['currentLogLoss'] as num).toDouble(),
      currentRMSE: (m['currentRmse'] as num).toDouble(),
      healthChecked: m['healthChecked'] as bool,
      healthPassed: m['healthPassed'] as bool,
      notEnoughReviews: m['notEnoughReviews'] as bool,
      minReviews: m['minReviews'] as int,
    );
  }

  /// Weights are the fitted FSRS parameters.
  final List<double> weights;

  /// Use reports whether they should replace the current parameters:
  /// they predict the review history better and, when the health check
  /// ran, pass it.
  final bool use;

  /// Better reports whether they predict the history better than the
  /// current parameters.
  final bool better;

  /// Reviews is the number of reviews learned from.
  final int reviews;

  /// LogLoss and RMSE measure how well Weights predict the reviews,
  /// CurrentLogLoss and CurrentRMSE the current parameters (lower is
  /// better).
  final double logLoss;

  final double rmse;

  final double currentLogLoss;

  final double currentRMSE;

  /// HealthChecked reports whether the health check ran, HealthPassed
  /// whether the parameters passed it.
  final bool healthChecked;

  final bool healthPassed;

  /// NotEnoughReviews is set when there were fewer than MinReviews
  /// reviews; then only Reviews is set besides it.
  final bool notEnoughReviews;

  final int minReviews;

  Map<String, Object?> toJson() => {
    'weights': weights,
    'use': use,
    'better': better,
    'reviews': reviews,
    'logLoss': logLoss,
    'rmse': rmse,
    'currentLogLoss': currentLogLoss,
    'currentRmse': currentRMSE,
    'healthChecked': healthChecked,
    'healthPassed': healthPassed,
    'notEnoughReviews': notEnoughReviews,
    'minReviews': minReviews,
  };

  @override
  String toString() => 'OptimizeResult(weights: $weights, use: $use, better: $better, reviews: $reviews, logLoss: $logLoss, rmse: $rmse, currentLogLoss: $currentLogLoss, currentRMSE: $currentRMSE, healthChecked: $healthChecked, healthPassed: $healthPassed, notEnoughReviews: $notEnoughReviews, minReviews: $minReviews)';
}

