/// SyncStatus is the state of device sync, streamed to the app.
class SyncStatus {
  const SyncStatus({
    required this.supported,
    required this.ready,
    this.deviceID,
    this.deviceName,
    required this.network,
    required this.trusted,
    required this.listening,
    this.port,
    this.address,
    required this.pairing,
    required this.paired,
    required this.discovered,
    required this.links,
    required this.syncing,
    this.progress,
    this.lastSynced,
    this.error,
  });

  factory SyncStatus.fromJson(Object? json) {
    final m = json as Map<String, dynamic>;
    return SyncStatus(
      supported: m['supported'] as bool,
      ready: m['ready'] as bool,
      deviceID: m['deviceId'] as String?,
      deviceName: m['deviceName'] as String?,
      network: NetworkInfo.fromJson(m['network']),
      trusted: (m['trusted'] as List<dynamic>?)?.map((x0) => TrustedNetwork.fromJson(x0)).toList() ?? const <TrustedNetwork>[],
      listening: m['listening'] as bool,
      port: m['port'] as int?,
      address: m['address'] as String?,
      pairing: m['pairing'] as bool,
      paired: (m['paired'] as List<dynamic>?)?.map((x0) => PairedDeviceInfo.fromJson(x0)).toList() ?? const <PairedDeviceInfo>[],
      discovered: (m['discovered'] as List<dynamic>?)?.map((x0) => DiscoveredDevice.fromJson(x0)).toList() ?? const <DiscoveredDevice>[],
      links: (m['links'] as List<dynamic>?)?.map((x0) => LinkInfo.fromJson(x0)).toList() ?? const <LinkInfo>[],
      syncing: m['syncing'] as bool,
      progress: switch (m['progress']) { final v0? => SyncProgress.fromJson(v0), _ => null },
      lastSynced: switch (m['lastSynced']) { final v0? => DateTime.parse(v0 as String), _ => null },
      error: m['error'] as String?,
    );
  }

  /// Supported is false on the web; Ready once the device has its sync
  /// identity (the Sync section was opened).
  final bool supported;

  final bool ready;

  final String? deviceID;

  final String? deviceName;

  /// DefaultName is what the device is called until the user names it.
  final NetworkInfo network;

  final List<TrustedNetwork> trusted;

  /// Listening is set while sync accepts connections, on Port, which the
  /// app announces; Address is this device's address for "Pair a device".
  final bool listening;

  final int? port;

  final String? address;

  /// Pairing is set while this device is visible for pairing.
  final bool pairing;

  final List<PairedDeviceInfo> paired;

  final List<DiscoveredDevice> discovered;

  /// Links are the open profile's links.
  final List<LinkInfo> links;

  /// Syncing is set while the open profile syncs, with Progress.
  final bool syncing;

  final SyncProgress? progress;

  /// LastSynced is the open profile's last finished sync; Error why the
  /// last one failed (a tagged text), empty if it did not.
  final DateTime? lastSynced;

  final String? error;

  Map<String, Object?> toJson() => {
    'supported': supported,
    'ready': ready,
    if (deviceID case final v0?) 'deviceId': v0,
    if (deviceName case final v0?) 'deviceName': v0,
    'network': network.toJson(),
    'trusted': [for (final x0 in trusted) x0.toJson()],
    'listening': listening,
    if (port case final v0?) 'port': v0,
    if (address case final v0?) 'address': v0,
    'pairing': pairing,
    'paired': [for (final x0 in paired) x0.toJson()],
    'discovered': [for (final x0 in discovered) x0.toJson()],
    'links': [for (final x0 in links) x0.toJson()],
    'syncing': syncing,
    if (progress case final v0?) 'progress': v0.toJson(),
    if (lastSynced case final v0?) 'lastSynced': v0.toUtc().toIso8601String(),
    if (error case final v0?) 'error': v0,
  };

  @override
  String toString() => 'SyncStatus(supported: $supported, ready: $ready, deviceID: $deviceID, deviceName: $deviceName, network: $network, trusted: $trusted, listening: $listening, port: $port, address: $address, pairing: $pairing, paired: $paired, discovered: $discovered, links: $links, syncing: $syncing, progress: $progress, lastSynced: $lastSynced, error: $error)';
}

